import 'dart:convert';
import 'dart:io';

/// Reads a JSON fixture generated by the Python app, by its path under
/// `test/fixtures/python_reference/`.
Map<String, dynamic> pythonReference(String relativePath) {
  final file = File('test/fixtures/python_reference/$relativePath');
  return jsonDecode(file.readAsStringSync()) as Map<String, dynamic>;
}

/// The maps of a JSON list.
List<Map<String, dynamic>> jsonObjects(Object? list) => [
  for (final item in list! as List<dynamic>) item as Map<String, dynamic>,
];
